def render_svg(theme, x, y, scale=2.3):
    dur_total = sum(DURATIONS) / 1000.0
    key_times = [0.0]
    cum = 0.0
    for d in DURATIONS:
        cum += d / 1000.0
        key_times.append(min(1.0, cum / dur_total))
    key_times[-1] = 1.0

    accent = theme.get("accent", "#088DDC")
    border = theme.get("border", "#2B3A45")

    resolved_palette = {}
    for cid_str, val in PALETTE.items():
        cid = int(cid_str)
        if val == "ACCENT":
            resolved_palette[cid] = f'fill="{accent}"'
        elif ":" in val:
            c, op = val.split(":")
            resolved_palette[cid] = f'fill="{c}" opacity="{op}"'
        else:
            resolved_palette[cid] = f'fill="{val}"'

    svg_parts = [
        f'<g id="terminal-basketball" transform="translate({x}, {y}) scale({scale})" shape-rendering="crispEdges">',
        f'  <line x1="6" y1="47" x2="106" y2="47" stroke="{border}" stroke-width="1" stroke-dasharray="2 2" opacity="0.5"/>',
    ]

    total_frames = len(FRAMES)
    kt_str = ";".join(f"{t:.3f}" for t in key_times[:-1])

    for idx, runs in enumerate(FRAMES):
        values = ["none"] * total_frames
        values[idx] = "inline"
        val_str = ";".join(values)
        disp = "inline" if idx == 6 else "none"
        cls = "bball-frame bball-hero" if idx == 6 else "bball-frame"

        svg_parts.append(f'  <g id="bball-f-{idx}" class="{cls}" display="{disp}">')
        svg_parts.append(f'    <animate attributeName="display" values="{val_str}" keyTimes="{kt_str}" dur="{dur_total:.2f}s" repeatCount="indefinite"/>')
        for rx, ry, rw, cid in runs:
            svg_parts.append(f'    <rect x="{rx}" y="{ry}" width="{rw}" height="1" {resolved_palette[cid]}/>')
        svg_parts.append('  </g>')

    svg_parts.append('</g>')
    return "\n".join(svg_parts)
